# Include a library of known optimal decompositions as templates:
def evolutionary_search(target, gate_set):
    library = load_decomposition_library()
    circuit = starting_circuit()
    for i in range(50000):
        if random() < 0.1 and target in library:
            # Direct template substitution — non-local jump
            circuit = library[target].instantiate()
        else:
            circuit = mutate(circuit)
        # ...
    return circuit

# Alternative: Use component-wise loss (e.g., per-basis-state error)
# instead of aggregate trace fidelity to create a gradual gradient:
def component_loss(candidate, target):
    # Sum of squared errors per matrix element
    # This gives gradual signal: changing one gate affects
    # specific matrix elements continuously
    diff = target.matrix - candidate.matrix
    return sum(abs(diff[i][j])**2 for i, j in all_indices)
